{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.slikk_master as WITH slikk_inv_metadata AS ( SELECT TRIM(UPPER(sku_group)) AS sku_group, ANY_VALUE(category) AS category, ANY_VALUE(title) AS title, ANY_VALUE(material_new) AS material_new, ANY_VALUE(print_design) AS print_design, ANY_VALUE(fit) AS fit, ANY_VALUE(sleeve_type) AS sleeve_type, ANY_VALUE(collar_new) AS collar_new FROM snitch_db.maplemonk.Slikk_INV_report GROUP BY 1 ), color_data AS ( SELECT TRIM(UPPER(sku_group)) AS sku_group, ANY_VALUE(color) AS color FROM snitch_db.maplemonk.metafields_data GROUP BY 1 ), inward_data AS ( SELECT TRIM(UPPER(SKU_GROUP)) AS SKU_GROUP, MIN(DATE) AS first_inward_date, SUM(OPENING_INVENTORY) AS opening_inventory FROM snitch_db.maplemonk.slikk_inventory GROUP BY 1 ), sales_after_inward AS ( SELECT TRIM(UPPER(k.SKU_GROUP)) AS SKU_GROUP, i.first_inward_date, SUM(CASE WHEN k.ORDER_DATE <= DATEADD(DAY, 7, i.first_inward_date) THEN TOTAL_QUANTITY ELSE 0 END) AS sales_day_7, SUM(CASE WHEN k.ORDER_DATE <= DATEADD(DAY, 15, i.first_inward_date) THEN TOTAL_QUANTITY ELSE 0 END) AS sales_day_15, SUM(CASE WHEN k.ORDER_DATE <= DATEADD(DAY, 30, i.first_inward_date) THEN TOTAL_QUANTITY ELSE 0 END) AS sales_day_30 FROM snitch_db.maplemonk.slikk_fact_item k JOIN inward_data i ON TRIM(UPPER(k.SKU_GROUP)) = i.SKU_GROUP GROUP BY 1, i.first_inward_date ), str_data AS ( SELECT s.SKU_GROUP, i.opening_inventory, DIV0(s.sales_day_7, i.opening_inventory) AS STR_DAY_7, DIV0(s.sales_day_15, i.opening_inventory) AS STR_DAY_15, DIV0(s.sales_day_30, i.opening_inventory) AS STR_DAY_30 FROM sales_after_inward s JOIN inward_data i ON s.SKU_GROUP = i.SKU_GROUP ), sku_group_data AS ( SELECT TRIM(UPPER(sku_group)) AS sku_group, order_date, SUM(TOTAL_QUANTITY) AS suborder_quantity, SUM(return_quantity) AS return_quantity, MAX(MRP) AS mrp, SUM(SP) AS SP FROM snitch_db.MAPLEMONK.slikk_fact_item GROUP BY 1, 2 ), first_order_dates AS ( SELECT sku_group, MIN(order_date) AS first_order_date, MAX(order_date) AS last_order_date, DATEDIFF(\'DAY\', MIN(order_date), CURRENT_DATE) AS days_since_first_order, DATEDIFF(\'DAY\', MAX(order_date), CURRENT_DATE) AS days_since_last_order, DATEDIFF(\'DAY\', MIN(order_date), MAX(order_date)) AS total_days_sold FROM sku_group_data GROUP BY 1 ), total_sales AS ( SELECT sgd.sku_group, fod.first_order_date, fod.last_order_date, fod.days_since_first_order, fod.days_since_last_order, fod.total_days_sold, MAX(MRP) AS MRP, DIV0(SUM(SP), SUM(suborder_quantity)) AS ASP, SUM(return_quantity) AS total_returns, SUM(suborder_quantity) AS total_sales, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 30, fod.first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_30_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 15, fod.first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_15_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 7, fod.first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_7_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 90, fod.first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_90_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 60, fod.first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_60_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 180, fod.first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_180_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 30 THEN suborder_quantity ELSE 0 END) AS sales_last_30_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 15 THEN suborder_quantity ELSE 0 END) AS sales_last_15_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 7 THEN suborder_quantity ELSE 0 END) AS sales_last_7_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 60 THEN suborder_quantity ELSE 0 END) AS sales_last_60_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 90 THEN suborder_quantity ELSE 0 END) AS sales_last_90_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 180 THEN suborder_quantity ELSE 0 END) AS sales_last_180_days, CASE WHEN fod.total_days_sold = 0 THEN SUM(suborder_quantity) ELSE DIV0(SUM(suborder_quantity), fod.total_days_sold) END AS natural_ros FROM sku_group_data sgd INNER JOIN first_order_dates fod ON sgd.sku_group = fod.sku_group GROUP BY sgd.sku_group, fod.first_order_date, fod.last_order_date, fod.days_since_first_order, fod.days_since_last_order, fod.total_days_sold ), enhanced_total_sales AS ( SELECT ts.*, GREATEST(DIV0(ts.sales_first_30_days, 30), DIV0(ts.sales_last_30_days, 30), ts.natural_ros) AS max_first_30_last_30_natural_ros, GREATEST(DIV0(ts.sales_first_30_days, 30), DIV0(ts.sales_last_30_days, 30), ts.natural_ros, DIV0(ts.sales_first_7_days, 7)) AS max_first_30_last_30_natural_ros_first_7_days, CASE WHEN ts.total_sales = 0 THEN 0 ELSE (ts.total_returns / ts.total_sales) * 100 END AS average_return_since_first_order, CASE WHEN (GREATEST(DIV0(ts.sales_first_30_days, 30), DIV0(ts.sales_last_30_days, 30), ts.natural_ros)) > 5 THEN (GREATEST(DIV0(ts.sales_first_30_days, 30), DIV0(ts.sales_last_30_days, 30), ts.natural_ros)) WHEN (GREATEST(DIV0(ts.sales_first_30_days, 30), DIV0(ts.sales_last_30_days, 30), ts.natural_ros)) < 5 AND (GREATEST(DIV0(ts.sales_first_30_days, 30), DIV0(ts.sales_last_30_days, 30), ts.natural_ros, DIV0(ts.sales_first_7_days, 7))) > 10 THEN (GREATEST(DIV0(ts.sales_first_30_days, 30), DIV0(ts.sales_last_30_days, 30), ts.natural_ros, DIV0(ts.sales_first_7_days, 7))) WHEN ts.total_sales > 800 THEN GREATEST(ts.natural_ros, DIV0(ts.sales_last_7_days, 7)) ELSE ts.natural_ros END AS final_ros FROM total_sales ts ), PivotTable AS ( WITH latest_inv_date AS (SELECT MAX(date) as max_date FROM snitch_db.maplemonk.Slikk_INV_report) SELECT TRIM(UPPER(sku_group)) AS sku_group, SUM(closing_inventory) AS Sellable_Inventory, SUM(CASE WHEN SIZE = \'XS\' OR SIZE = \'28\' THEN closing_inventory ELSE 0 END) AS XS_units, SUM(CASE WHEN SIZE = \'S\' OR SIZE = \'30\' THEN closing_inventory ELSE 0 END) AS S_units, SUM(CASE WHEN SIZE = \'M\' OR SIZE = \'32\' THEN closing_inventory ELSE 0 END) AS M_units, SUM(CASE WHEN SIZE = \'L\' OR SIZE = \'34\' THEN closing_inventory ELSE 0 END) AS L_units, SUM(CASE WHEN SIZE = \'XL\' OR SIZE = \'36\' THEN closing_inventory ELSE 0 END) AS XL_units, SUM(CASE WHEN SIZE IN (\'XXL\', \'2XL\', \'38\') THEN closing_inventory ELSE 0 END) AS XXL_units, SUM(CASE WHEN SIZE = \'3XL\' OR SIZE = \'40\' THEN closing_inventory ELSE 0 END) AS XL3_units, SUM(CASE WHEN SIZE = \'4XL\' OR SIZE = \'42\' THEN closing_inventory ELSE 0 END) AS XL4_units, SUM(CASE WHEN SIZE = \'5XL\' OR SIZE = \'44\' THEN closing_inventory ELSE 0 END) AS XL5_units, SUM(CASE WHEN SIZE = \'6XL\' OR SIZE = \'46\' THEN closing_inventory ELSE 0 END) AS XL6_units, SUM(CASE WHEN SIZE = \'7XL\' OR SIZE = \'48\' THEN closing_inventory ELSE 0 END) AS XL7_units, SUM(CASE WHEN SIZE = \'8XL\' OR SIZE = \'50\' THEN closing_inventory ELSE 0 END) AS XL8_units, SUM(CASE WHEN SIZE IS NULL THEN closing_inventory ELSE 0 END) AS NA_units, COUNT(DISTINCT CASE WHEN closing_inventory > 0 THEN SIZE ELSE NULL END) AS num_size_available FROM snitch_db.maplemonk.Slikk_INV_report WHERE date = (SELECT max_date FROM latest_inv_date) AND LOWER(sku_group) NOT LIKE \'cb%\' GROUP BY 1 ), availability_master_v2 AS ( SELECT TRIM(UPPER(sku_group)) AS sku_group, ANY_VALUE(PRODUCT_NAME) AS PRODUCT_NAME, ANY_VALUE(CATEGORY) AS CATEGORY, ANY_VALUE(SKU_CLASS) AS SKU_CLASS, SUM(SELLABLE_INVENTORY) AS SELLABLE_INVENTORY, SUM(XS_UNITS) AS XS_UNITS, SUM(S_UNITS) AS S_UNITS, SUM(M_UNITS) AS M_UNITS, SUM(L_UNITS) AS L_UNITS, SUM(XL_UNITS) AS XL_UNITS, SUM(XXL_UNITS) AS XXL_UNITS, SUM(XL3_UNITS) AS XL3_UNITS, SUM(XL4_UNITS) AS XL4_UNITS, SUM(XL5_UNITS) AS XL5_UNITS, SUM(XL6_UNITS) AS XL6_UNITS, SUM(XL7_UNITS) AS XL7_UNITS, SUM(XL8_UNITS) AS XL8_UNITS, SUM(NA_UNITS) AS NA_units, SUM(NUM_SIZE_AVAILABLE) AS NUM_SIZE_AVAILABLE FROM snitch_db.maplemonk.availability_master_v2 GROUP BY 1 ), category_sales_ranked AS ( SELECT meta.category, e.sku_group, e.total_sales, SUM(e.total_sales) OVER (PARTITION BY meta.category) AS category_total_sales, SUM(e.total_sales) OVER ( PARTITION BY meta.category ORDER BY e.total_sales DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cumulative_sales FROM enhanced_total_sales e LEFT JOIN slikk_inv_metadata meta ON e.sku_group = meta.sku_group ), category_pareto AS ( SELECT *, DIV0(cumulative_sales, category_total_sales) * 100 AS cumulative_sales_pct, CASE WHEN DIV0(cumulative_sales, category_total_sales) * 100 <= 40 THEN \'Top 40%\' WHEN DIV0(cumulative_sales, category_total_sales) * 100 <= 80 THEN \'40-80%\' ELSE \'Bottom 20%\' END AS pareto_segment FROM category_sales_ranked ), slikk_base_prep AS ( SELECT a.sku_group, CASE WHEN (CASE WHEN b.M_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN b.L_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN b.XL_units > 0 THEN 1 ELSE 0 END) < 3 THEN \'Cut Size\' ELSE \'Full Size\' END AS CUTE_SIZE_FAG, a.days_since_first_order, a.days_since_last_order, cp.cumulative_sales_pct, cp.pareto_segment FROM enhanced_total_sales a FULL OUTER JOIN PivotTable b ON a.sku_group = b.sku_group LEFT JOIN category_pareto cp ON a.sku_group = cp.sku_group ), production_base AS ( SELECT * FROM ( SELECT TRIM(UPPER(ADJUSTED_SKU)) AS SKU_GROUP, STATUS, REVISED_DELIVERY_DATE, PROJ_QTY, COALESCE(CUT_QTY, 0) AS CUT_QTY, ROW_NUMBER() OVER (PARTITION BY ADJUSTED_SKU, STATUS ORDER BY 1 DESC) AS rn FROM snitch_db.maplemonk.production_data WHERE STATUS = \'Active\' ) WHERE rn = 1 ), pullback_scoring AS ( SELECT s.SKU_GROUP, p.STATUS, p.REVISED_DELIVERY_DATE, p.PROJ_QTY, p.CUT_QTY, CASE WHEN s.CUTE_SIZE_FAG = \'Cut Size\' THEN 5 ELSE 0 END AS score_cut_size, CASE WHEN s.PARETO_SEGMENT = \'Bottom 20%\' THEN 5 WHEN s.PARETO_SEGMENT = \'40-80%\' THEN 2.5 WHEN s.PARETO_SEGMENT = \'Top 40%\' THEN 0 ELSE 5 END AS score_pareto, CASE WHEN s.DAYS_SINCE_FIRST_ORDER > 100 THEN 5 WHEN s.DAYS_SINCE_FIRST_ORDER >= 50 THEN 2.5 WHEN s.DAYS_SINCE_FIRST_ORDER >= 30 THEN 1.5 WHEN s.DAYS_SINCE_FIRST_ORDER IS NULL THEN 5 ELSE 0 END AS score_first_order, CASE WHEN s.DAYS_SINCE_LAST_ORDER > 45 THEN 5 WHEN s.DAYS_SINCE_LAST_ORDER >= 30 THEN 2.5 WHEN s.DAYS_SINCE_LAST_ORDER >= 15 THEN 1.5 WHEN s.DAYS_SINCE_LAST_ORDER IS NULL THEN 5 ELSE 0 END AS score_last_order FROM slikk_base_prep s LEFT JOIN production_base p ON s.SKU_GROUP = p.SKU_GROUP ), pullback_final AS ( SELECT *, ROUND(score_cut_size * 0.30 + score_pareto * 0.40 + score_first_order * 0.1 + score_last_order * 0.2, 2) AS total_score, CASE WHEN (score_cut_size * 0.30 + score_pareto * 0.40 + score_first_order * 0.1 + score_last_order * 0.2) <= 1.5 THEN \'Good - No Pullback\' WHEN (score_cut_size * 0.30 + score_pareto * 0.40 + score_first_order * 0.1 + score_last_order * 0.2) <= 2.75 THEN \'Low - Consider\' WHEN (score_cut_size * 0.30 + score_pareto * 0.40 + score_first_order * 0.1 + score_last_order * 0.2) <= 4.0 THEN \'Mid - Consider\' ELSE \'High - Pullback\' END AS pullback_decision, DATEDIFF(\'DAY\', CURRENT_DATE, REVISED_DELIVERY_DATE) AS Days_to_inward FROM pullback_scoring ), add_remark AS ( SELECT *, CASE WHEN pullback_decision IN (\'Low - Consider\', \'Mid - Consider\') THEN CASE WHEN score_cut_size >= GREATEST(score_pareto, score_first_order, score_last_order) AND score_pareto >= GREATEST(score_first_order, score_last_order) THEN \'Cut Size, Low Pareto\' WHEN score_cut_size >= GREATEST(score_pareto, score_first_order, score_last_order) AND score_first_order >= GREATEST(score_pareto, score_last_order) THEN \'Cut Size, Old First Order\' WHEN score_cut_size >= GREATEST(score_pareto, score_first_order, score_last_order) AND score_last_order >= GREATEST(score_pareto, score_first_order) THEN \'Cut Size, No Recent Sale\' WHEN score_pareto >= GREATEST(score_cut_size, score_first_order, score_last_order) AND score_cut_size >= GREATEST(score_first_order, score_last_order) THEN \'Low Pareto, Cut Size\' WHEN score_pareto >= GREATEST(score_cut_size, score_first_order, score_last_order) AND score_first_order >= GREATEST(score_cut_size, score_last_order) THEN \'Low Pareto, Old First Order\' WHEN score_pareto >= GREATEST(score_cut_size, score_first_order, score_last_order) AND score_last_order >= GREATEST(score_cut_size, score_first_order) THEN \'Low Pareto, No Recent Sale\' WHEN score_first_order >= GREATEST(score_cut_size, score_pareto, score_last_order) AND score_cut_size >= GREATEST(score_pareto, score_last_order) THEN \'Old First Order, Cut Size\' WHEN score_first_order >= GREATEST(score_cut_size, score_pareto, score_last_order) AND score_pareto >= GREATEST(score_cut_size, score_last_order) THEN \'Old First Order, Low Pareto\' WHEN score_first_order >= GREATEST(score_cut_size, score_pareto, score_last_order) AND score_last_order >= GREATEST(score_cut_size, score_pareto) THEN \'Old First Order, No Recent Sale\' ELSE \'No Recent Sale, Cut Size\' END ELSE NULL END AS sub_remark FROM pullback_final ), pullback_agg AS ( SELECT TRIM(UPPER(SKU_GROUP)) AS sku_group, SUM(PULLBACK_INVENTORY) AS total_pullback_inventory FROM snitch_db.maplemonk.slikk_inventory GROUP BY sku_group ), replen_skus AS ( SELECT DISTINCT TRIM(UPPER(sku_code)) AS sku_group FROM snitch_db.maplemonk.qcom_replen_4_july2025 ), raw_last_inward AS ( WITH inv_sent_raw AS ( SELECT CASE WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-S\' THEN \'4MSN1310-05-S\' WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-M\' THEN \'4MSN1310-05-M\' ELSE upper(trim(sku)) END AS sku, TO_DATE(TRIM(_AB_ADDITIONAL_PROPERTIES:\"Date \"), \'DD-MM-YYYY\') AS inward_date, SUM(TRY_TO_NUMBER(TRIM(_AB_ADDITIONAL_PROPERTIES:\"Qty Sent \"))) AS qty_sent FROM snitch_db.maplemonk.S3_SLIKK_inventory GROUP BY 1, 2 ) SELECT TRIM(UPPER(REGEXP_REPLACE(sku, \'-[^-]*$\', \'\'))) AS sku_group, MAX(CASE WHEN qty_sent > 0 THEN inward_date ELSE NULL END) AS last_inward_date FROM inv_sent_raw GROUP BY 1 ) SELECT COALESCE(a.sku_group, b.sku_group) AS sku_group, a.first_order_date, a.last_order_date, a.days_since_first_order, a.days_since_last_order, a.total_days_sold, a.MRP, a.ASP, a.total_returns, a.total_sales, a.sales_first_30_days, a.sales_first_15_days, a.sales_first_7_days, a.sales_first_90_days, a.sales_first_60_days, a.sales_first_180_days, a.sales_last_30_days, a.sales_last_15_days, a.sales_last_7_days, a.sales_last_60_days, a.sales_last_90_days, a.sales_last_180_days, a.natural_ros, a.max_first_30_last_30_natural_ros, a.max_first_30_last_30_natural_ros_first_7_days, a.average_return_since_first_order, a.final_ros, d.opening_inventory, rli.last_inward_date, d.STR_DAY_7, d.STR_DAY_15, d.STR_DAY_30, b.SELLABLE_INVENTORY, b.XS_UNITS, b.S_UNITS, b.M_UNITS, b.L_UNITS, b.XL_UNITS, b.XXL_UNITS, b.XL3_UNITS, b.XL4_UNITS, b.XL5_UNITS, b.XL6_UNITS, b.XL7_UNITS, b.XL8_UNITS, b.NA_UNITS, b.num_size_available, sb.CUTE_SIZE_FAG, CASE WHEN ( CASE WHEN b.M_units > 0 THEN 1 ELSE 0 END + CASE WHEN b.L_units > 0 THEN 1 ELSE 0 END + CASE WHEN b.XL_units > 0 THEN 1 ELSE 0 END ) < 3 AND b.SELLABLE_INVENTORY > 0 AND m.CATEGORY NOT IN (\'Sunglasses\', \'Perfumes\') THEN CASE WHEN c.M_UNITS <= 3 OR c.L_UNITS <= 3 OR c.XL_UNITS <= 3 THEN \'No Stock In Warehouse\' WHEN replen.sku_group IS NOT NULL THEN \'Replen\' ELSE \'Low ROS, Do Not Replen\' END ELSE NULL END AS cut_size_style_reason, DIV0((a.TOTAL_SALES - a.TOTAL_RETURNS), (a.TOTAL_SALES - a.TOTAL_RETURNS + B.SELLABLE_INVENTORY)) * 100 AS Sell_through, DIV0(B.SELLABLE_INVENTORY, (DIV0(a.SALES_LAST_30_DAYS, 30))) AS DOI, c.PRODUCT_NAME, COALESCE(m.category, c.CATEGORY) AS CATEGORY, c.SKU_CLASS, c.SELLABLE_INVENTORY AS warehouse_inventory, c.XS_UNITS AS warehouse_XS_UNITS, c.S_UNITS AS warehouse_S_UNITS, c.M_UNITS AS warehouse_M_UNITS, c.L_UNITS AS warehouse_L_UNITS, c.XL_UNITS AS warehouse_XL_UNITS, c.XXL_UNITS AS warehouse_XXL_UNITS, c.XL3_UNITS AS warehouse_XL3_UNITS, c.XL4_UNITS AS warehouse_XL4_UNITS, c.XL5_UNITS AS warehouse_XL5_UNITS, c.XL6_UNITS AS warehouse_XL6_UNITS, c.XL7_UNITS AS warehouse_XL7_UNITS, c.XL8_UNITS AS warehouse_XL8_UNITS, c.NA_UNITS AS warehouse_NA_UNITS, c.NUM_SIZE_AVAILABLE AS warehouse_NUM_SIZE_AVAILABLE, m.TITLE, m.PRINT_DESIGN, m.COLLAR_NEW, m.MATERIAL_NEW, m.FIT, col.COLOR, m.SLEEVE_TYPE, cp.cumulative_sales_pct, cp.pareto_segment, pf.status, pf.revised_delivery_date, pf.proj_qty, pf.cut_qty, pf.score_cut_size, pf.score_pareto, pf.score_first_order, pf.score_last_order, pf.total_score, CASE WHEN b.Sellable_Inventory <= 0 THEN \'0 Sellable Inv\' ELSE pf.pullback_decision END AS pullback_decision, pf.Days_to_inward, ar.sub_remark, pa.total_pullback_inventory FROM enhanced_total_sales a FULL OUTER JOIN PivotTable b ON a.sku_group = b.sku_group LEFT JOIN str_data d ON COALESCE(a.sku_group, b.sku_group) = d.sku_group LEFT JOIN availability_master_v2 c ON COALESCE(a.sku_group, b.sku_group) = c.sku_group LEFT JOIN slikk_inv_metadata m ON COALESCE(a.sku_group, b.sku_group) = m.sku_group LEFT JOIN color_data col ON COALESCE(a.sku_group, b.sku_group) = col.sku_group LEFT JOIN category_pareto cp ON COALESCE(a.sku_group, b.sku_group) = cp.sku_group LEFT JOIN pullback_final pf ON COALESCE(a.sku_group, b.sku_group) = pf.sku_group LEFT JOIN slikk_base_prep sb ON COALESCE(a.sku_group, b.sku_group) = sb.sku_group LEFT JOIN add_remark ar ON COALESCE(a.sku_group, b.sku_group) = ar.sku_group LEFT JOIN pullback_agg pa ON COALESCE(a.sku_group, b.sku_group) = pa.sku_group LEFT JOIN replen_skus replen ON COALESCE(a.sku_group, b.sku_group) = replen.sku_group LEFT JOIN raw_last_inward rli ON COALESCE(a.sku_group, b.sku_group) = rli.sku_group ORDER BY a.total_sales DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            